# CRC64-ISO (poly 0xD800000000000000, init 0xFFFFFFFFFFFFFFFF, refin True, ...)
# Let's implement table-driven for ECMA with reflected poly 0xC96C5795D7870F42 reversed?

def make_table(poly_reflected):
    tbl=[]
    for i in range(256):
        crc=i
        for _ in range(8):
