# Output routing
class OutStreams:
    def __init__(self):
        self.bso = 1  # 0 disable, 1 stdout, 2 stderr
        self.bse = 2
        self.bsp = 1
        self.bso_explicit = False
    def out(self, s):
        if self.bso == 0:
            return
        elif self.bso == 1:
            sys.stdout.write(s)
        elif self.bso == 2:
            sys.stderr.write(s)
    def err(self, s):
        if self.bse == 0:
            return
        elif self.bse == 1:
            sys.stdout.write(s)
        elif self.bse == 2:
            sys.stderr.write(s)
    def out_always(self, s):
        # for l listing which always goes to stdout
        sys.stdout.write(s)

streams = OutStreams()

def eprint_cmd_error(msg):
    # Command Line Error goes to stderr via bse? Actually with default bse=2, goes to stderr.
    # But header goes via bso. For errors before header? No, header already printed via bso, error via bse.
    # Format: "\n\nCommand Line Error:\n<msg>\n"
    # msg may contain newlines? e.g., "Unsupported command:\nbadcmd"
    s = "\n\nCommand Line Error:\n" + msg + "\n"
    streams.err(s)

