# 7z helpers
def enc_u64(n):
    if n < 0x80: return bytes([n])
    for extra in range(1,8):
        hb = 7 - extra
        mx = (1 << (hb + 8*extra)) - 1
        if n <= mx:
            high = n >> (8*extra)
            prefix = (0xFF << (8-extra)) & 0xFF if extra<8 else 0xFF
            out = bytes([prefix | high])
            for i in range(extra-1,-1,-1): out += bytes([(n >> (8*i)) & 0xFF])
            return out
    return bytes([0xFF]) + n.to_bytes(8,'big')
def dec_u64(buf, pos):
    b=buf[pos]; pos+=1
    if b < 0x80: return b, pos
    mask=0x80; extra=0
    for i in range(8):
        if b & mask == 0: break
        extra+=1; mask >>=1
    if extra==8:
        return int.from_bytes(buf[pos:pos+8],'big'), pos+8
    high = b & (mask-1) if mask>0 else 0
    v=high
    for i in range(extra):
        v=(v<<8)|buf[pos]; pos+=1
    return v, pos

def filetime_to_unix(ft):
    # Windows FILETIME (100ns since 1601) to unix
    try: return ft/10000000 - 11644473600
    except: return 0
def unix_to_filetime(t):
    return int((t + 11644473600)*10000000)

def lzma2_compress(data, dict_bits=None):
    # choose dict bits like 7-Zip: max(12, bitlen)
    if dict_bits is None:
        if len(data)==0: dict_bits=12
        else: dict_bits=max(12, (len(data)-1).bit_length())
        if dict_bits>30: dict_bits=30
    # props = (dict_bits-12)*2 for small? For larger need different? Use simple
    # For now dict size = 1<<dict_bits, but lzma may not support huge? Clamp to 1<<27?
    ds = 1 << min(dict_bits, 27)
    try:
        c=lzma.compress(data, format=lzma.FORMAT_RAW, filters=[{"id": lzma.FILTER_LZMA2, "dict_size": ds}])
        return c, dict_bits
    except:
        c=lzma.compress(data, format=lzma.FORMAT_RAW, filters=[{"id": lzma.FILTER_LZMA2}])
        return c, dict_bits
def lzma2_decompress(data):
    return lzma.decompress(data, format=lzma.FORMAT_RAW, filters=[{"id": lzma.FILTER_LZMA2}])

